import numpy as np
def equation(eps, T, params):
    a,b,f,g,m,n,q,r,p,s=params[0],params[1],params[2],params[3],params[4],params[5],params[6],params[7],params[8],params[9]
    u=T-2
    return -(a*np.tanh(b*eps**p*np.exp(f*u))*np.exp(g*u) + m*eps*(T/2)**n + q*eps**2*np.exp(r*u) + s*eps*np.exp(0*u))
